import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import stompClient from '../socket/socket';
import GameBoard from '../components/GameBoard';
import DiceButton from '../components/DiceButton';

const LudoGamePage = () => {
  const { gameId } = useParams();
  // TODO: playerId should be dynamic, e.g. from auth context or props
  const [playerId] = useState(0);
  const [boardState, setBoardState] = useState(null);
  const [connected, setConnected] = useState(false);

  useEffect(() => {
    // Ensure stompClient is inactive before activating
    if (stompClient.active) {
      stompClient.deactivate();
    }

    // onConnect is a function, use onConnect callback param instead of assignment for multiple usage safety
    const onConnectHandler = () => {
      console.log('WebSocket connected ✅');
      setConnected(true);

      // Subscribe to game updates for this gameId
      stompClient.subscribe(`/topic/game/${gameId}`, (msg) => {
        try {
          const data = JSON.parse(msg.body);
          setBoardState(data);
        } catch (e) {
          console.error('Invalid JSON in WebSocket message:', e);
        }
      });
    };

    // Attach handlers and activate
    stompClient.onConnect = onConnectHandler;
    stompClient.onStompError = (frame) => {
      console.error('Broker reported error: ' + frame.headers['message']);
      console.error('Details: ' + frame.body);
    };
    stompClient.onWebSocketClose = (event) => {
      console.log('WebSocket closed:', event);
      setConnected(false);
    };
    stompClient.activate();

    return () => {
      stompClient.deactivate();
      setConnected(false);
      setBoardState(null);
    };
  }, [gameId]);

  const sendMove = (tokenIndex, diceValue) => {
    if (!connected) {
      console.warn('Not connected yet - cannot send move');
      return;
    }

    const moveRequest = {
      gameId: parseInt(gameId),
      playerId,
      tokenIndex,
      diceValue,
    };

    stompClient.publish({
      destination: '/app/game/move',
      body: JSON.stringify(moveRequest),
    });
  };

  const handleLeave = () => {
    if (!connected) {
      console.warn('Not connected yet - cannot leave game');
      return;
    }
    stompClient.publish({
      destination: '/app/game/leave',
      body: JSON.stringify({ gameId: parseInt(gameId), playerId }),
    });
  };

  if (!connected) return <p>Connecting to game...</p>;
  if (!boardState) return <p>Waiting for board state...</p>;

  return (
    <div style={styles.container}>
      <h2 style={styles.title}>Game ID: {gameId}</h2>

      <GameBoard
        boardData={boardState.playerTokens}
        currentPlayer={boardState.currentPlayer}
        playerId={playerId}
        onMove={sendMove}
      />

      <DiceButton onRoll={(dice) => sendMove(0, dice)} />

      <button onClick={handleLeave} style={styles.leaveBtn}>
        Leave Game
      </button>

      {boardState.gameOver && <p style={styles.winMsg}>Game Over!</p>}
    </div>
  );
};

const styles = {
  container: {
    maxWidth: 600,
    margin: '0 auto',
    padding: 20,
    textAlign: 'center',
  },
  title: {
    marginBottom: 20,
    fontWeight: 'bold',
    fontSize: '1.5rem',
  },
  leaveBtn: {
    marginTop: 20,
    background: '#f87171',
    color: 'white',
    padding: '10px 20px',
    border: 'none',
    borderRadius: 6,
    cursor: 'pointer',
  },
  winMsg: {
    marginTop: 20,
    color: 'green',
    fontWeight: 'bold',
  },
};

export default LudoGamePage;
